function highlight(text, tokens){
  const safe = escapeHtml(text);
  if(!tokens.length) return safe;
  // Highlight only where a typed word matches from the start of a word.
  const re = new RegExp('\\b('+tokens.map(esc).join('|')+')','ig');
  return safe.replace(re,'<mark>$1</mark>');
}

function render(term){
  // Treat the query as a set of words: spaces are fine, order doesn't matter,
  // and every word just has to match from the start of a word somewhere in
  // the bookmark (so "read" finds "reading" but not "bread").
  const tokens = term.trim().toLowerCase().split(/\s+/).filter(Boolean);
  const tokenRes = tokens.map(tok => new RegExp('\\b' + esc(tok), 'i'));
  const matches = bookmarks.filter(b => {
    if(!tokens.length) return true;
    const hay = (b.title + ' ' + b.desc + ' ' + b.source + ' ' + b.site).toLowerCase();
    return tokenRes.every(re => re.test(hay));
  });

