function renderSuggest(){
  const typed=$('labelInput').value.trim().toLowerCase();
  let existing=[...new Set(bookmarks.flatMap(b=>b.tags))].filter(t=>!pendingTags.includes(t));
  // As you type, narrow to the labels you already have (so "rec" points at "recipe").
  if(typed) existing=existing.filter(t=>t.toLowerCase().includes(typed));
  const heading = typed ? 'Did you mean: ' : 'Reuse a label: ';
  $('suggest').innerHTML = existing.length ? heading+existing.map(t=>`<button data-t="${escapeHtml(t)}">${escapeHtml(t)}</button>`).join('') : '';
  $('suggest').querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{ pendingTags.push(b.getAttribute('data-t')); $('labelInput').value=''; renderChips(); renderSuggest(); }));
}

