        const parsed = raw ? JSON.parse(raw) : [];
        return Array.isArray(parsed) ? parsed.map(normalizeItem) : [];
      } catch (e) { return []; }
    }
    function persist() {
      try { storage.setItem(ITEMS_KEY, JSON.stringify(items)); } catch (e) { /* storage full/blocked */ }
    }
    function normalizeItem(it) {
      return {
