:root { --ink:#1f2328; --muted:#6b7280; --line:#e5e7eb; --accent:#2563eb; --bg:#f7f8fa; }
* { box-sizing:border-box; }
body { margin:0; font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif; color:var(--ink); background:var(--bg); }
.wrap { max-width:720px; margin:0 auto; padding:32px 20px 96px; }
.top { display:flex; align-items:baseline; justify-content:space-between; gap:12px; }
h1 { font-size:22px; margin:0 0 4px; }
.sub { color:var(--muted); margin:0 0 20px; font-size:14px; }
.add-btn { border:none; background:var(--accent); color:#fff; font-size:14px; font-weight:600; padding:10px 16px; border-radius:10px; cursor:pointer; white-space:nowrap; }
.add-btn:hover { background:#1d4ed8; }

#asideBar { margin:-8px 0 12px; font-size:13px; }
#asideBar a { color:var(--muted); text-decoration:none; }
#asideBar a:hover { color:var(--accent); }
#readBar { margin:0 0 12px; }
.readtoggle { font-size:14px; font-weight:600; padding:8px 14px; border-radius:10px; background:#fffbeb; color:#92400e; border:1px solid #fde68a; cursor:pointer; }
.readtoggle:hover { border-color:#f59e0b; }
.readtoggle.on { background:#f59e0b; color:#fff; border-color:#f59e0b; }

.adder { background:#fff; border:1px solid var(--line); border-radius:12px; padding:16px; margin:0 0 20px; display:none; }
.adder.open { display:block; }
.adder h2 { font-size:15px; margin:0 0 12px; }
.field { margin:0 0 12px; }
.field label { display:block; font-size:12px; color:var(--muted); margin:0 0 4px; }
.field input, .field textarea { width:100%; font-size:14px; padding:10px 12px; border:1px solid var(--line); border-radius:8px; outline:none; background:#fff; font-family:inherit; }
.field input:focus, .field textarea:focus { border-color:var(--accent); box-shadow:0 0 0 3px rgba(37,99,235,.12); }
.field textarea { min-height:56px; resize:vertical; }
.autofilled { font-size:11px; color:#059669; margin-left:6px; }
.preview { display:none; }
.preview.show { display:block; }
.dupe { background:#fff7ed; border:1px solid #fed7aa; color:#9a3412; padding:12px; border-radius:8px; margin:0 0 12px; font-size:14px; display:none; }
.dupe button { border:none; background:#fdba74; color:#7c2d12; border-radius:6px; padding:4px 10px; cursor:pointer; margin-left:8px; font-size:13px; }
.warn { color:#b45309; font-size:13px; margin:0 0 10px; display:none; }
.row-btns { display:flex; gap:8px; margin-top:4px; align-items:center; }
.save { border:none; background:var(--accent); color:#fff; font-weight:600; font-size:14px; padding:10px 18px; border-radius:8px; cursor:pointer; }
.save:disabled { background:#cbd5e1; cursor:default; }
.cancel { border:1px solid var(--line); background:#fff; color:#334155; font-size:14px; padding:10px 16px; border-radius:8px; cursor:pointer; }
.aside-btn { margin-left:auto; border:1px solid var(--line); background:#fff; color:#334155; font-size:13px; padding:9px 14px; border-radius:8px; cursor:pointer; display:none; }
.aside-btn:hover { border-color:var(--accent); color:var(--accent); }
.delete { border:1px solid #fecaca; background:#fff; color:#b91c1c; font-size:13px; padding:9px 14px; border-radius:8px; cursor:pointer; display:none; }
.delete.armed { background:#dc2626; color:#fff; border-color:#dc2626; }
.chips-in { display:flex; flex-wrap:wrap; gap:6px; align-items:center; border:1px solid var(--line); border-radius:8px; padding:6px 8px; }
.chips-in input { border:none; outline:none; box-shadow:none !important; flex:1; min-width:120px; padding:4px; }
.chip-editable { font-size:12px; padding:3px 8px; border-radius:999px; background:#eef2ff; color:#3730a3; border:1px solid #c7d2fe; display:inline-flex; gap:6px; align-items:center; }
.chip-editable button { border:none; background:none; color:#3730a3; cursor:pointer; font-size:13px; line-height:1; padding:0; }
.suggest { margin-top:8px; font-size:12px; color:var(--muted); }
.suggest button { font-size:12px; padding:3px 9px; border-radius:999px; background:#f1f5f9; color:#334155; border:1px solid #e2e8f0; cursor:pointer; margin:0 4px 4px 0; }
.suggest button:hover { border-color:#c7d2fe; }
.reading-field label { display:flex; align-items:center; gap:8px; cursor:pointer; color:var(--ink); font-size:14px; }
.reading-field input { width:auto; }

.search { position:sticky; top:0; background:var(--bg); padding:12px 0 10px; z-index:2; }
.search input { width:100%; font-size:17px; padding:14px 16px; border:1px solid var(--line); border-radius:10px; outline:none; background:#fff; }
.search input:focus { border-color:var(--accent); box-shadow:0 0 0 3px rgba(37,99,235,.12); }
.tagbar { display:flex; flex-wrap:wrap; gap:8px; margin:0 0 6px; padding-bottom:6px; }
.tagbar .label { font-size:12px; color:var(--muted); align-self:center; margin-right:2px; }
.filter { font-size:13px; padding:5px 12px; border-radius:999px; background:#fff; color:#334155; border:1px solid #e2e8f0; cursor:pointer; }
.filter:hover { border-color:#c7d2fe; }
.filter.on { background:var(--accent); color:#fff; border-color:var(--accent); }
.clear { font-size:13px; padding:5px 12px; border-radius:999px; background:#fee2e2; color:#991b1b; border:1px solid #fecaca; cursor:pointer; margin-left:4px; }
.listbar { display:flex; align-items:center; justify-content:space-between; gap:12px; margin:4px 2px 14px; }
.count { color:var(--muted); font-size:13px; }
.sort { color:var(--muted); font-size:13px; display:flex; align-items:center; }
.sort select { font-size:13px; padding:4px 8px; border:1px solid var(--line); border-radius:8px; background:#fff; color:var(--ink); cursor:pointer; }

ul { list-style:none; margin:0; padding:0; }
li { background:#fff; border:1px solid var(--line); border-radius:10px; padding:14px 16px; margin-bottom:10px; }
li.fresh { animation:pop .6s ease; border-color:#86efac; }
@keyframes pop { from { background:#f0fdf4; } to { background:#fff; } }
.card-head { display:flex; justify-content:space-between; align-items:flex-start; gap:8px; }
.title { font-size:16px; font-weight:600; margin:0 0 3px; }
.title a { color:var(--ink); text-decoration:none; }
.title a:hover { text-decoration:underline; }
.edit-btn { flex:none; border:1px solid var(--line); background:#fff; color:#64748b; font-size:12px; padding:4px 10px; border-radius:8px; cursor:pointer; }
.edit-btn:hover { border-color:var(--accent); color:var(--accent); }
.site { color:var(--accent); font-size:12px; margin:0 0 6px; }
.desc { color:#374151; font-size:14px; margin:0 0 8px; line-height:1.45; }
