.tag.on { background:var(--accent); color:#fff; border-color:var(--accent); }
.tag .x { margin-left:6px; color:#94a3b8; cursor:pointer; font-weight:700; }
.tag .x:hover { color:#dc2626; }
.add-label { font-size:12px; padding:3px 9px; border-radius:999px; background:#fff; color:#64748b; border:1px dashed #cbd5e1; cursor:pointer; }
.add-label:hover { border-color:var(--accent); color:var(--accent); }
