.site { color:var(--accent); font-size:12px; margin:0 0 6px; }
.desc { color:#374151; font-size:14px; margin:0 0 8px; line-height:1.45; }
.note-edit { font-size:14px; line-height:1.45; color:#3730a3; border-left:3px solid #c7d2fe; padding:4px 10px; margin:0 0 8px; outline:none; border-radius:0 6px 6px 0; }
.note-edit:focus { background:#f5f3ff; border-left-color:var(--accent); }
.add-note { background:none; border:none; color:#818cf8; font-size:12px; cursor:pointer; padding:2px 0; margin:0 0 8px; }
.add-note:hover { color:var(--accent); text-decoration:underline; }
.date { color:var(--muted); font-size:12px; margin:0 0 8px; }
.tags { display:flex; flex-wrap:wrap; gap:6px; align-items:center; }
.tag { font-size:12px; padding:3px 9px; border-radius:999px; background:#f1f5f9; color:#334155; border:1px solid #e2e8f0; cursor:pointer; }
