.tag.on { background:var(--accent); color:#fff; border-color:var(--accent); }
.tag .x { margin-left:6px; color:#94a3b8; cursor:pointer; font-weight:700; }
.tag .x:hover { color:#dc2626; }
.add-label { font-size:12px; padding:3px 9px; border-radius:999px; background:#fff; color:#64748b; border:1px dashed #cbd5e1; cursor:pointer; }
.add-label:hover { border-color:var(--accent); color:var(--accent); }
.add-label-input { font-size:12px; padding:3px 8px; border-radius:999px; border:1px solid var(--accent); outline:none; width:110px; }
.to-read-btn { font-size:12px; padding:3px 9px; border-radius:999px; background:#fff; color:#b45309; border:1px dashed #fcd34d; cursor:pointer; }
.to-read-btn:hover { border-color:#f59e0b; background:#fffbeb; }
.toread-badge { font-size:12px; padding:3px 9px; border-radius:999px; background:#fffbeb; color:#92400e; border:1px solid #fde68a; font-weight:600; }
.mark-read { font-size:12px; padding:3px 9px; border-radius:999px; background:#fff; color:#047857; border:1px solid #a7f3d0; cursor:pointer; }
.mark-read:hover { background:#ecfdf5; border-color:#34d399; }
.aside-actions { display:flex; gap:8px; margin-top:8px; }
mark { background:#fde68a; color:inherit; padding:0 1px; border-radius:2px; }
.empty { color:var(--muted); text-align:center; padding:48px 12px; line-height:1.5; }
.empty strong { color:var(--ink); }
#toast { position:fixed; left:50%; bottom:24px; transform:translateX(-50%); background:#1f2937; color:#fff; padding:10px 14px; border-radius:10px; display:none; align-items:center; gap:14px; font-size:14px; box-shadow:0 8px 24px rgba(0,0,0,.2); z-index:10; }
